/*
 *  Sends the test parameter structure and number of tests
 */
void
recip_getTestParams (recip_testParams_t ** params, int32_t * numTests)
{
   *params = testParams;
   *numTests = sizeof (testParams) / sizeof (recip_testParams_t);
}

